(()=>{if(new URLSearchParams(location.search).get("waterlight")==="0"){document.querySelector("link[data-water-light]")?.remove();return}const ROWS=".fi-menu-links button",TAP=".fi-copy-action, .fiwo-pill, .fiwp-next, .fiw-outro-links button, .fi-menu-toggle, .fi-footer button, .fiw-top, .fi-menu-links button, .fi-menu-close",place=(el,e)=>{const r=el.getBoundingClientRect();el.style.setProperty("--mx",(e.clientX-r.left).toFixed(1)+"px"),el.style.setProperty("--my",(e.clientY-r.top).toFixed(1)+"px")};addEventListener("pointermove",e=>{if(e.pointerType!=="mouse")return;const row=e.target instanceof Element?e.target.closest(ROWS):null;row&&place(row,e)},{passive:!0});const timers=new WeakMap;addEventListener("pointerdown",e=>{if(e.pointerType==="mouse")return;const el=e.target instanceof Element?e.target.closest(TAP):null;el&&(place(el,e),el.classList.add("wl-tap"),clearTimeout(timers.get(el)),timers.set(el,setTimeout(()=>el.classList.remove("wl-tap"),700)))},{passive:!0,capture:!0})})();